\noindent
\begin{minipage}[c]{0.58\textwidth}
\zadnum На рисунку зображено графік лінійної функції $y = 3x - 2$. Графік якої з наведених функцій паралельний графіку цієї функції?
\end{minipage}
\hfill
\begin{minipage}[c]{0.40\textwidth}
\centering
\begin{nmtfit}\begin{tikzpicture}[scale=0.45, thick]
    \draw[gray!30, very thin] (-4.5,-4.5) grid (4.5,4.5);
    \draw[->, thick] (-4.7,0) -- (4.7,0) node[right] {\small $x$};
    \draw[->, thick] (0,-4.7) -- (0,4.7) node[above] {\small $y$};
    \node[below left] at (0,0) {\scriptsize $0$};
    \node[below] at (1,-0.1) {\scriptsize $1$};
    \node[left] at (-0.1,1) {\scriptsize $1$};
    \draw[thick, mainGreen, line width=1.2pt] (-0.8,-4.4) -- (2.1,4.3);
    \node[mainGreen, fill=white, inner sep=1pt, anchor=west] at (1.6,1) {\scriptsize $y = 3x - 2$};
\end{tikzpicture}\end{nmtfit}
\end{minipage}
\par\nbvspace{0.2cm}
\answerTableTall{$y = -3x - 2$}{$y = -2x + 3$}{$y = \dfrac{x}{3} - 2$}{$y = -\dfrac{1}{3}x + 1$}{$y = 5 + 3x$}

